(() => {
  const api=window.desktop?.connections;
  let connections=[],busy=null,feedback='',failure=false;
  const names={codex:'Codex',claude:'Claude Code',gemini:'Gemini CLI'};
  window.ruangConnectionLabel=i=>{const id=state.agentConnections?.[i],c=connections.find(c=>c.id===id);return c?.enabled?c.name+' ? '+c.status:(id?names[id]+' ? disconnected':'No connection assigned')};
  const company={codex:'OpenAI',claude:'Anthropic',gemini:'Google'};
  const clean=e=>e.message.replace(/^Error invoking remote method '[^']+': Error: /,'');
  const fallback=Object.entries(names).map(([id,name])=>({id,name,company:company[id],status:'Desktop required',installed:false}));
  function controls(c){const disabled=busy?'disabled':'';return `<div class="connection-controls"><button class="primary" data-connect="login" data-id="${c.id}" ${disabled} ${!c.installed?'disabled':''}>${c.id==='gemini'?'Sign in with Google':'Sign in to '+esc(c.name)}</button><button data-connect="key" data-id="${c.id}" ${disabled}>${c.hasKey?'Replace API key':'Use API key'}</button>${c.enabled?`<button data-connect="check" data-id="${c.id}" ${disabled}>${c.mode==='api'?'Check API key':'Check sign-in'}</button><button data-connect="disconnect" data-id="${c.id}" ${disabled}>Disconnect from Ruang</button>`:''}</div>`}
  function panel(){const list=connections.length?connections:fallback;return `<section class="panel pad connection-intro"><div class="row"><div><h2>AI Connections</h2><p class="muted">Connect your coding tools or use your own API keys.</p></div><button data-connect="refresh" ${busy||!api?'disabled':''}>Refresh connections</button></div><p class="notice">Connections are real. Office tasks and chat remain demos in this version; connecting does not start an agent or send your project files.</p>${!api?'<p class="notice">Open the Ruang desktop app to connect accounts. This browser preview cannot store keys or open local tools.</p>':''}<p class="connection-feedback ${failure?'danger':''}" role="status">${esc(feedback||'Sign-in opens the official tool and browser. Finish there, then check the connection here.')}</p></section><div class="connections-grid">${list.map(c=>`<section class="panel pad connection-card"><div class="row"><h2>${esc(c.name)}</h2>${badge(c.status,c.status==='API verified'||c.status==='Signed in'?'':'demo')}</div><p class="muted">${esc(c.company)} · ${c.mode==='api'?'API key · separate API billing':c.mode==='cli'?'Official tool sign-in':'Not linked'}</p><p class="small">${c.installed?'Official tool detected':'Official tool not detected'}${c.mode==='api'?' · not required for API keys':''}</p>${c.detail?`<p class="small muted">${esc(c.detail)}</p>`:''}${c.checkedAt?`<p class="small muted">Last check: ${esc(new Date(c.checkedAt).toLocaleString())}</p>`:''}${api?controls(c):''}<details><summary>Setup and sign-in details</summary><p class="small muted">${c.id==='gemini'?'In Gemini choose Sign in with Google, or use /auth to change account. Gemini does not expose a standalone login-status command; Ruang will not claim this session is verified. API-key connections can be verified here.':'Ruang checks the official tool’s authentication status. Sign-in alone does not establish available model quota.'}</p><p class="small muted">The official tool keeps its own login. Disconnect only unlinks it from Ruang; it does not sign you out of other apps. API keys saved here are separate from CLI sign-in.</p>${api?`<div class="connection-controls">${!c.installed?`<button data-connect="install" data-id="${c.id}" ${busy?'disabled':''}>Install official tool</button>`:''}<button data-connect="choose" data-id="${c.id}" ${busy?'disabled':''}>Locate installed tool</button><button data-connect="docs" data-id="${c.id}">Official setup guide</button></div>`:''}</details></section>`).join('')}</div>${assignments()}<section class="panel pad"><h2>Local workspace</h2><p class="small muted">Choose a project folder under Files to read and edit local text files with confirmation and backups.</p><button data-action="export">Export workspace</button><p class="small muted">Exports contain projects and preferences, never connection credentials.</p></section>`}
  function assignments(){return `<section class="panel pad connection-assignments"><h2>Employee connections</h2><p class="small muted">Choose the connection each employee will use when live execution is added. Tasks currently remain simulated.</p>${state.agents.map((a,i)=>`<div class="connection-assignment"><label for="connection-agent-${i}">${esc(a.name)} <span class="muted">· ${esc(a.role)}</span></label><select id="connection-agent-${i}" data-connection-agent="${i}"><option value="">No connection</option>${Object.entries(names).map(([id,name])=>`<option value="${id}" ${state.agentConnections?.[i]===id?'selected':''}>${name}${connections.find(c=>c.id===id)?.enabled?'':' · disconnected'}</option>`).join('')}</select></div>`).join('')}</section>`}
  const baseBody=bodyView;bodyView=function(p){if(view==='Settings')return panel();return baseBody(p)};
  async function refresh(){if(!api)return;connections=await api.list();window.ruangConnections=connections;if(view==='Settings')render()}
  function keyDialog(id){show(`<h2>Connect ${esc(company[id])} API</h2><p>Ruang will send your key only to ${esc(company[id])} to check its model list. No prompt or project files are sent.</p><p class="small muted">Keys use Windows-protected storage and are excluded from workspace exports. API billing is separate from a chat subscription. This check does not establish generation quota.</p><form id="connection-key-form" data-id="${id}"><label for="connection-secret">API key</label><input id="connection-secret" type="password" autocomplete="off" spellcheck="false" required maxlength="4096"><p id="connection-key-result" role="status"></p><div class="dialog-actions"><button type="button" data-close>Cancel</button><button class="primary">Verify and save</button></div></form>`)}
  document.addEventListener('submit',async e=>{if(e.target.id!=='connection-key-form')return;e.preventDefault();const form=e.target,id=form.dataset.id,input=$('#connection-secret'),button=form.querySelector('button.primary');if(busy)return;let key=input.value;input.value='';busy=id;button.disabled=true;button.textContent='Checking…';try{connections=await api.saveKey(id,key);key='';feedback=names[id]+' API key verified and saved.';failure=false;$('#dialog').close();await refresh()}catch(error){$('#connection-key-result').textContent=clean(error)}finally{key='';busy=null;button.disabled=false;form.querySelector('[data-close]').disabled=false;button.textContent='Verify and save';if(!$('#dialog').open)render()}});
  $('#dialog').addEventListener('cancel',e=>{if(busy&&$('#connection-key-form'))e.preventDefault()});
  document.addEventListener('change',e=>{const index=e.target.dataset.connectionAgent;if(index===undefined)return;state.agentConnections||={};state.agentConnections[index]=e.target.value;persist()});
  document.addEventListener('click',async e=>{const b=e.target.closest('[data-connect]');if(!b||!api||busy)return;const action=b.dataset.connect,id=b.dataset.id;
    if(action==='key'){keyDialog(id);return}
    busy=id||'refresh';feedback='Working…';failure=false;if(view==='Settings')render();
    try{if(action==='refresh')await refresh();if(action==='login')await api.login(id);if(action==='install'){await api.install(id);feedback='Installer opened. After it finishes, refresh and choose Sign in.'}if(action==='choose')await api.chooseTool(id);if(action==='docs')await api.docs(id);if(action==='check'){const c=connections.find(c=>c.id===id);await (c.mode==='api'?api.checkAPI(id):api.checkCLI(id))}if(action==='disconnect')await api.disconnect(id);if(action!=='install')feedback=action==='login'?'Finish sign-in in the official tool, then return and check the connection.':action==='disconnect'?'Disconnected from Ruang. Any saved Ruang API key was removed. Official tool sign-ins are unchanged.':'Connections updated.';await refresh()}
    catch(error){feedback=clean(error);failure=true;try{connections=await api.list()}catch{}}
    finally{busy=null;if(view==='Settings')render()}
  });
  document.addEventListener('click',e=>{if(e.target.closest('[data-view="Settings"]'))refresh().catch(error=>{feedback=clean(error);failure=true;if(view==='Settings')render()})});
  refresh().catch(()=>{});if(view==='Settings')render();
})();
